CAT = "ea1Advising"; SEG = "ADV"
# Advising the individual taxpayer (SEE Part 1 domain 5). Tax year 2025 unless stated.
_ann_tax = 5000 - 5000 * 60000 // 100000; assert _ann_tax == 2000

Q = [
("A used car dealer, a sole proprietor, receives $14,000 in currency from one buyer for a car. The dealer must file:",
 "Form 8300 within 15 days", ["Form 1099-NEC by January 31", "FinCEN Form 114 by April 15", "No form at all"],
 "A business that receives more than $10,000 in cash in one transaction or related transactions must file Form 8300 within 15 days."),
("A client sells gold coins she held for three years at a gain. The highest rate on that gain is:",
 "28%", ["20%", "25%", "37%"],
 "Gold coins are collectibles. Long-term collectibles gain is taxed at up to 28%, not the 20% top capital gain rate."),
("A client sells her sole proprietorship, including equipment, inventory and goodwill, for one price. For tax purposes the sale is treated:",
 "As a sale of each asset", ["As one capital asset sale", "As ordinary income in full", "As a like-kind exchange"],
 "A sole proprietorship is not one asset. The price is allocated among the assets under the residual method, reported on Form 8594, and each asset's gain keeps its own character."),
("A parent takes $6,000 from a 529 plan and spends it on a vacation. The earnings part of the withdrawal is:",
 "Taxable plus a 10% tax", ["Tax-free", "Taxable with no extra tax", "Taxable plus a 20% tax"],
 "A nonqualified 529 withdrawal is partly a tax-free return of contributions. The earnings part is taxable and usually subject to a 10% additional tax."),
("Under SECURE 2.0, a 529 account beneficiary may roll unused funds to her Roth IRA up to a lifetime limit of:",
 "$35,000", ["$70,000", "$50,000", "$100,000"],
 "A 529 open at least 15 years can roll up to $35,000 over the beneficiary's lifetime into her Roth IRA, subject to the annual Roth contribution limit."),
("Funds in a Coverdell education savings account generally must be used or distributed by the time the beneficiary reaches age:",
 "30", ["18", "26", "21"],
 "A Coverdell balance must be distributed within 30 days after the beneficiary turns 30, unless the beneficiary has special needs. A rollover to a younger family member avoids tax."),
("A family pays $4,000 of tuition with a 529 distribution and also wants the American opportunity credit. The rule is that:",
 "Expenses cannot count twice", ["Both use the full $4,000", "The credit bars any 529 use", "The 529 money is all taxable"],
 "Expenses used for the education credit reduce the qualified expenses for the 529 distribution, so the same dollars cannot be both tax-free and credited."),
("A client puts her investments in a revocable living trust to avoid probate. At her death, the trust assets are:",
 "In her gross estate", ["Out of her gross estate", "Half in her gross estate", "In the trustee's estate"],
 "Because she could revoke the trust and take the assets back, they are included in her gross estate under sections 2036 and 2038. A revocable trust avoids probate, not estate tax."),
("A client wants life insurance proceeds kept out of her taxable estate. A common plan is to have the policy owned by:",
 "An irrevocable insurance trust", ["Her own revocable living trust", "Her and her spouse jointly", "Her estate as beneficiary"],
 "If an irrevocable trust owns the policy and she holds no incidents of ownership, the proceeds are not in her gross estate. A policy she transfers within three years of death is still included."),
("For a parent's gift of a family partnership interest to a child to be respected for income tax, capital must be:",
 "A material income-producing factor", ["Contributed by the child herself", "Worth over $1 million in total", "Held in a trust for 10 years"],
 "Under section 704(e), a donee partner is recognized if capital is a material income-producing factor and the donee truly owns the interest. In a pure service business, the income stays with whoever earns it."),
("Benefits paid under a qualified long-term care insurance contract are generally:",
 "Excluded like health benefits", ["Fully taxable income", "Taxed as an annuity", "Taxable above $1,000"],
 "A qualified long-term care contract is treated as accident and health insurance. Its reimbursements are excluded, and per diem benefits are excluded up to a daily limit."),
("A retiree's annuity cost $60,000 and has an expected return of $100,000. Of each $5,000 payment, the taxable part is:",
 "$2,000", ["$3,000", "$5,000", "$2,500"],
 "The exclusion ratio is $60,000 / $100,000 = 60%, so $3,000 of each payment is a return of cost and $2,000 is taxable until the cost is recovered."),
("A 74-year-old has $8,000 of her IRA's required distribution sent directly to a public charity. The $8,000 is:",
 "Excluded, and counts toward her RMD", ["Taxable, then a charitable deduction", "Taxable with no deduction", "Excluded, but not toward her RMD"],
 "A qualified charitable distribution from an IRA owner 70 1/2 or older is excluded from income and counts toward the RMD. No charitable deduction is allowed for it."),
("A qualified charitable distribution from an IRA cannot be made to:",
 "A donor-advised fund", ["A church", "A public university", "A food bank charity"],
 "Qualified charitable distributions must go to public charities, but not to donor-advised funds or supporting organizations."),
("At 52, a client starts substantially equal periodic payments from his IRA. To keep the 10% exception, he must continue them until:",
 "Later of 5 years or 59 1/2", ["He reaches age 55 or retires", "Five years have passed", "He reaches age 62"],
 "A section 72(t) payment stream must last until the later of five years or age 59 1/2. Changing it earlier triggers the 10% tax, plus interest, on past payments."),
("As part of a 2025 divorce, Ned transfers stock with a $40,000 basis, worth $90,000, to his former wife. The result is:",
 "No gain; her basis is $40,000", ["$50,000 gain to Ned", "No gain; her basis is $90,000", "$50,000 income to her"],
 "Section 1041 treats transfers between spouses or incident to divorce as gifts: no gain or loss, and the receiving spouse takes the transferor's basis."),
("A divorce decree from 2017 is modified in 2025. Payments under it become nondeductible to the payer only if the change:",
 "Expressly adopts the new rules", ["Changes the payment amount", "Is ordered by a court", "Adds a new child support term"],
 "Instruments executed before 2019 keep the old alimony treatment unless a later modification expressly states that the post-2018 rules apply."),
("Spouses in a community property state file separate returns. Each generally reports:",
 "Half of community income", ["Only his or her own wages", "All income in their name", "The higher earner's share"],
 "In a community property state, each spouse filing separately reports half of the community income and all of his or her separate income, with some exceptions in Publication 555."),
("A couple formed a valid common-law marriage in a state that allows it and then moved to a state that does not. For federal tax they are:",
 "Married", ["Unmarried", "Married only in that state", "Married if they wed again"],
 "A common-law marriage valid in the state where it was entered into is recognized for federal tax purposes, wherever the couple later lives."),
("A client's 2025 net operating loss, not from farming, is carried to 2026. It can offset at most what share of 2026 taxable income figured before the NOL?",
 "80%", ["100%", "50%", "90%"],
 "NOLs arising after 2017 carry forward without a time limit but can offset only 80% of taxable income (before the NOL deduction) in a carryforward year. They generally cannot be carried back."),
("A sole proprietor's business had negative qualified business income in 2025. The negative amount:",
 "Reduces next year's QBI", ["Is lost at year end", "Offsets wages this year", "Is carried back a year"],
 "Negative total QBI produces no deduction and carries forward as a loss that reduces QBI in the next year."),
("A spouse seeking innocent spouse relief under section 6015(b) or (c) must generally request it on Form 8857 within:",
 "2 years of first collection", ["3 years of filing the return", "10 years of filing", "1 year of divorce"],
 "The request is due within two years after the IRS begins collection activity against the requesting spouse. Equitable relief can have a longer period."),
("A married couple files a joint return that understates tax because of one spouse's income. Unless relief applies, the IRS can collect:",
 "The full tax from either spouse", ["Half from each spouse", "Only from the spouse who earned it", "Only from joint assets"],
 "A joint return makes both spouses jointly and severally liable for the whole tax, interest and penalties."),
("A taxpayer filed her 2023 return on April 15, 2024 and paid in full then. To get a refund she must file a claim by:",
 "April 15, 2027", ["April 15, 2026", "April 15, 2028", "December 31, 2026"],
 "A refund claim must be filed within 3 years from when the return was filed or 2 years from payment, whichever is later. Both start April 15, 2024, so 3 years gives April 15, 2027."),
("By signing a return under penalties of perjury, a paid preparer declares it is true and complete based on:",
 "All information he knows", ["Only the client's documents", "What the client verbally said", "IRS transcripts alone"],
 "The preparer's declaration is based on all information of which the preparer has any knowledge; the taxpayer's declaration covers the whole return."),
("A cash-basis itemizer wants a $2,000 charitable gift deducted in 2025. She charges it to her credit card on December 31, 2025 and pays the card in January. The gift is deductible in:",
 "2025", ["2026", "Half in each year", "Neither year"],
 "A charitable contribution charged to a credit card is deductible in the year charged, even if the card balance is paid the next year."),
("A client has $20,000 of short-term capital gains realized in 2025. Before year end, the most direct way to lower the tax on them is to:",
 "Sell a stock held at a loss", ["Buy more of that stock", "Delay her 2025 filing", "Convert gains to wages"],
 "Realized capital losses offset capital gains first, so harvesting a loss before year end reduces the short-term gain, which is otherwise taxed at ordinary rates. Watch the wash sale rule if she rebuys."),
("Compared with a joint return, a married couple filing separately cannot deduct:",
 "Student loan interest", ["Mortgage interest", "State income taxes", "Charitable gifts"],
 "The student loan interest deduction is not allowed for married filing separately. Mortgage interest, taxes and gifts can still be itemized, though if one spouse itemizes the other must too."),
]
